#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeMobileAppStore: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = MobileAppStore

    public static func lift(_ handle: UInt64) throws -> MobileAppStore {
        return MobileAppStore(unsafeFromHandle: handle)
    }

    public static func lower(_ value: MobileAppStore) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MobileAppStore {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: MobileAppStore, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeMobileAppStore_lift(_ handle: UInt64) throws -> MobileAppStore {
    return try FfiConverterTypeMobileAppStore.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeMobileAppStore_lower(_ value: MobileAppStore) -> UInt64 {
    return FfiConverterTypeMobileAppStore.lower(value)
}






/**
 * Durable adapter used by the iOS `umsh_hal::CounterStore` boundary.
 *
 * Each commit writes and synchronizes a temporary record, atomically renames
 * it over the previous boundary, then synchronizes the containing directory.
 * An error at any stage is treated as ambiguous by the caller and therefore
 * cannot release a prepared authenticated frame for transmission.
 *
 * Every operation runs on one thread of the store's own, in the order it
 * was asked for: the fsyncs never hold the thread that drives the MAC, and
 * a commit whose caller stopped waiting still lands before any asked for
 * after it, so a newer boundary is never overwritten by an older one. The
 * caller learns that a boundary is durable only from the thread's reply.
 */
public protocol MobileCounterStoreProtocol: AnyObject, Sendable {

    func commitBoundary(context: Data, boundary: UInt32) throws

    func loadBoundary(context: Data) throws  -> UInt32

}
/**
 * Durable adapter used by the iOS `umsh_hal::CounterStore` boundary.
 *
 * Each commit writes and synchronizes a temporary record, atomically renames
 * it over the previous boundary, then synchronizes the containing directory.
 * An error at any stage is treated as ambiguous by the caller and therefore
 * cannot release a prepared authenticated frame for transmission.
 *
 * Every operation runs on one thread of the store's own, in the order it
 * was asked for: the fsyncs never hold the thread that drives the MAC, and
 * a commit whose caller stopped waiting still lands before any asked for
 * after it, so a newer boundary is never overwritten by an older one. The
 * caller learns that a boundary is durable only from the thread's reply.
 */
open class MobileCounterStore: MobileCounterStoreProtocol, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_umsh_mobile_core_fn_clone_mobilecounterstore(self.handle, $0) }
    }
public convenience init(rootDirectory: String)throws  {
    let handle =
        try rustCallWithError(FfiConverterTypeCounterStoreError_lift) {
        uniffiCallStatus in
    uniffi_umsh_mobile_core_fn_constructor_mobilecounterstore_new(
        FfiConverterString.lower(rootDirectory),uniffiCallStatus
    )
}
    self.init(unsafeFromHandle: handle)
}

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_umsh_mobile_core_fn_free_mobilecounterstore(handle, $0) }
    }




open func commitBoundary(context: Data, boundary: UInt32)throws   {try rustCallWithError(FfiConverterTypeCounterStoreError_lift) {
        uniffiCallStatus in
    uniffi_umsh_mobile_core_fn_method_mobilecounterstore_commit_boundary(
            self.uniffiCloneHandle(),
        FfiConverterData.lower(context),
        FfiConverterUInt32.lower(boundary),uniffiCallStatus
    )
}
