     */
    public var lanBearerState: UInt8?
    public var devKey: Data?
    public var battery: UlcpBatteryRecord?
    /**
     * Ambient light in millilux. Empty means a measurement was unavailable.
     */
    public var illuminanceMillilux: UInt32?
    /**
     * Tenths of kelvin; inner None is an unavailable sensor.
     */
    public var temperatures: [UInt16?]?
    public var temperatureNames: [String]?
    public var phyEnabled: Bool?
    public var frequencyKhz: UInt32?
    public var transmitPowerDbm: Int8?
    public var bandwidthHz: UInt32?
    public var spreadingFactor: UInt8?
    public var codingRateDenom: UInt8?
    public var dutyCycleNow: UInt16?
    /**
     * `PROP_PHY_RX_DUTY`: the share of the past hour other transmitters
     * occupied the channel, on the scale of `duty_cycle_now`.
     */
    public var rxDutyCycle: UInt16?
    public var dutyCycleLimit: UInt16?
    public var statTxPackets: UInt32?
    public var statTxChannelBusy: UInt32?
    public var statRxPackets: UInt32?
    public var statRxBadCrc: UInt32?
    public var statRxNonUmsh: UInt32?
    public var statRxAccepted: UInt32?
    public var statRadioResets: UInt32?
    public var statForwarded: UInt32?
    public var statForwardDropped: UInt32?
    public var statForwardCancelled: UInt32?
