/**
 * Work produced by the Rust ULCP session. Frames are complete ULCP
 * frames; the platform adapter remains responsible for GATT segmentation and
 * write backpressure.
 */
public struct UlcpSessionUpdateRecord: Equatable, Hashable {
    public var outboundFrames: [Data]
    public var receivedFrames: [UlcpReceivedFrameRecord]
    public var snapshot: UlcpSessionSnapshotRecord
    public var waitingForResponses: Bool
    /**
     * Outstanding non-raw transactions, for transport recovery deadlines.
     * Unsolicited updates preserve these IDs; raw PHY completion has its own
     * longer deadline and must not disable control-plane recovery.
     */
    public var pendingControlTransactions: Data
    /**
     * A control response consumed by this update. An allocator may reuse its
     * ID immediately; the new request must receive a fresh deadline.
     */
    public var completedControlTransaction: UInt8?
    /**
     * True while one host-requested raw PHY transmission is awaiting the
     * radio's `PROP_LAST_STATUS` completion.
     */
    public var rawTransmitPending: Bool
    /**
     * Transaction allocated by `transmit_raw` in this update, if any.
     */
    public var rawTransmitStartedTransactionId: UInt8?
    /**
     * Completion for the raw PHY transmission consumed by this update.
     * Rejections are ordinary radio-level send failures, not malformed
     * ULCP frames.
     */
    public var rawTransmitResult: UlcpRawTransmitResultRecord?
    /**
     * Non-transmit operation error consumed by this update. The ULCP
     * session has already recovered to a stable stage and remains usable.
     */
    public var operationError: UlcpOperationErrorRecord?
    /**
     * A correlated answer this session could not use, reported on the
     * update that settles the operation it belonged to—after any read-back
     * it triggered—so whoever is waiting on that operation finds it on the
     * update that completes the operation. The session remains attached.
     */
    public var mismatchedResponse: UlcpMismatchedResponseRecord?
    /**
     * Completion of the local management operation, when this update
     * carries one.
     */
    public var managementEvent: UlcpLocalManagementEventRecord?
    /**
     * Values the device announced unsolicited with this update, verbatim.
     * The snapshot has already absorbed what it recognizes; these carry
     * the raw octets to whoever caches values by property number.
     */
    public var pushedProperties: [UlcpPropertyPushRecord]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(outboundFrames: [Data], receivedFrames: [UlcpReceivedFrameRecord], snapshot: UlcpSessionSnapshotRecord, waitingForResponses: Bool,
        /**
         * Outstanding non-raw transactions, for transport recovery deadlines.
         * Unsolicited updates preserve these IDs; raw PHY completion has its own
         * longer deadline and must not disable control-plane recovery.
         */pendingControlTransactions: Data,
        /**
         * A control response consumed by this update. An allocator may reuse its
         * ID immediately; the new request must receive a fresh deadline.
         */completedControlTransaction: UInt8?,
        /**
         * True while one host-requested raw PHY transmission is awaiting the
         * radio's `PROP_LAST_STATUS` completion.
         */rawTransmitPending: Bool,
        /**
         * Transaction allocated by `transmit_raw` in this update, if any.
         */rawTransmitStartedTransactionId: UInt8?,
        /**
         * Completion for the raw PHY transmission consumed by this update.
         * Rejections are ordinary radio-level send failures, not malformed
         * ULCP frames.
         */rawTransmitResult: UlcpRawTransmitResultRecord?,
        /**
         * Non-transmit operation error consumed by this update. The ULCP
         * session has already recovered to a stable stage and remains usable.
         */operationError: UlcpOperationErrorRecord?,
        /**
         * A correlated answer this session could not use, reported on the
         * update that settles the operation it belonged to—after any read-back
         * it triggered—so whoever is waiting on that operation finds it on the
         * update that completes the operation. The session remains attached.
         */mismatchedResponse: UlcpMismatchedResponseRecord?,
        /**
         * Completion of the local management operation, when this update
         * carries one.
         */managementEvent: UlcpLocalManagementEventRecord?,
        /**
         * Values the device announced unsolicited with this update, verbatim.
         * The snapshot has already absorbed what it recognizes; these carry
         * the raw octets to whoever caches values by property number.
         */pushedProperties: [UlcpPropertyPushRecord]) {
        self.outboundFrames = outboundFrames
        self.receivedFrames = receivedFrames
        self.snapshot = snapshot
        self.waitingForResponses = waitingForResponses
        self.pendingControlTransactions = pendingControlTransactions
        self.completedControlTransaction = completedControlTransaction
        self.rawTransmitPending = rawTransmitPending
        self.rawTransmitStartedTransactionId = rawTransmitStartedTransactionId
        self.rawTransmitResult = rawTransmitResult
        self.operationError = operationError
        self.mismatchedResponse = mismatchedResponse
        self.managementEvent = managementEvent
        self.pushedProperties = pushedProperties
    }




}

